INSERT OR REPLACE INTO recipes (slug, json, updated_at) VALUES ('chicken-soup-stock', '{"slug":"chicken-soup-stock","title":"Chicken Soup + Stock","description":"A 16-quart pot of chicken soup, made every week, enjoyed Friday night with leftovers on Sunday. Make Wednesday morning, cook all day, refrigerate overnight, then reboil and simmer Friday morning for Shabbos.","tags":["Soups"],"servings":"1 (16-quart pot, large batch)","prepTime":"Not specified","cookTime":"About 9 hours (40 min boil, 8 hr simmer)","image":"","ingredients":["2 whole chickens, cut into eighths (skin removed)","5 carrots, peeled, cut into 2-inch pieces","2 yellow onions, peeled","1 leek, white and light green only, chopped","1 stalk celery, peeled, cut into 2-inch pieces","2 zucchini, cut into 2-inch pieces","1 kohlrabi, peeled","2 parsnips, peeled, cut into 2-inch pieces","1 celery root, peeled","2 cups fresh dill","2 cups fresh parsley greens","1 cup cilantro","2 tbsp whole black peppercorns","3 tbsp kosher salt","2 pieces flanken (optional)","1 turkey neck (optional)"],"steps":["Add chicken to one mesh bag, vegetables to a second, and dill, parsley, cilantro, and peppercorns to a third (flanken or turkey neck to a fourth if using).","Place a very large pot (16 quarts) over high heat. Sear the chicken bag dry for 6 to 8 minutes, turning every few minutes.","Once browned, fill the pot with water at the sink (it should turn slightly golden). Add the vegetable and herb bags while filling. Add salt.","Return to heat uncovered; boil about 40 minutes, skimming foam.","Reduce heat to lowest, cover, and simmer 8 hours or overnight.","Remove from heat, cool 2 hours, and separate the vegetables from the soup.","Refrigerate. To use as stock, strain to clarify, then ladle into containers.","If serving Friday night: remove from the fridge 4 hours before Shabbos, boil, then reduce heat and simmer until Shabbos."],"notes":"Special equipment: 3 to 4 mesh soup bags. To serve, remove the bags, place vegetables in a shallow bowl, shred the chicken (and flanken or turkey) and add to the bowl, then ladle broth over. Use stock for rice, couscous, chicken dishes, braises, other soups, sauces, or a quick mug of soup. For matzah balls: heat soup Friday, transfer bags to a 9x13 pan with a few ladles of broth, cover, and place on the blech; portion stock for the freezer, then cook matzah balls directly in the pot to keep the frozen soup clear.","source":{"url":"","name":"Peas, Love & Carrots"},"updatedAt":"2026-10-20T12:00:00Z"}', '2026-10-20T12:00:00Z');
INSERT OR REPLACE INTO recipes (slug, json, updated_at) VALUES ('copycat-blueberry-mamma-chia-squeeze', '{"slug":"copycat-blueberry-mamma-chia-squeeze","title":"Copycat Blueberry Mamma Chia Squeeze","description":"A simple, healthy snack made from pureed blueberries, chia seeds, a touch of honey, and water.","tags":["Other"],"servings":"2","prepTime":"10 min","cookTime":"None (2 hr resting/refrigeration)","image":"","ingredients":["1/2 cup frozen blueberries","2 tbsp chia seeds","2/3 cup water","1 tbsp lemon juice","1 tsp honey (or maple syrup for infants under 1 year)"],"steps":["Blend blueberries, water, and honey on high until pureed, about 1 minute.","Add chia seeds to a jar; pour the blueberry puree over the seeds.","Stir in lemon juice; mix thoroughly for even seed distribution.","Refrigerate 2 hours or overnight until thickened.","Consume with a spoon or straw; store refrigerated up to one week."],"notes":"Use fresh or frozen fruit; fresh requires less water. Experiment with strawberries, mixed berries, or fruit-vegetable combinations. Store in reusable pouches for convenience; freezer-safe in individual portions.","source":{"url":"https://wellnessforwomanhood.com/2020/05/20/copycat-mamma-chia-squeeze/","name":"Wellness for Womanhood"},"updatedAt":"2026-10-20T12:00:00Z"}', '2026-10-20T12:00:00Z');
INSERT OR REPLACE INTO recipes (slug, json, updated_at) VALUES ('cottage-cheese-pancakes', '{"slug":"cottage-cheese-pancakes","title":"Cottage Cheese Pancakes","description":"Easy and packed with extra protein, these fluffy, light pancakes deliver 15 grams of protein per serving without using protein powder. Ready in under 30 minutes.","tags":["Baking"],"servings":"4 (about 12 pancakes)","prepTime":"10 min","cookTime":"20 min","image":"","ingredients":["1¼ cup flour (all-purpose or whole wheat)","2 tsp baking powder","1 cup cottage cheese","3 large eggs","2 tbsp milk of choice (up to ¼ cup for a thinner batter)","2 tbsp melted, cooled coconut oil","1 tbsp maple syrup","1 tsp vanilla extract"],"steps":["Mix dry ingredients together in a large bowl.","Blend cottage cheese, eggs, and milk until smooth.","Gently combine wet and dry ingredients.","Stir in coconut oil, maple syrup, and vanilla.","Heat a non-stick skillet over medium heat; cook pancakes until edges dry and bubbles form.","Flip and cook 1 to 2 minutes until tops soften.","Stack and serve with syrup."],"notes":"Allow coconut oil to cool before adding to prevent clumping. Avoid overmixing batter to prevent tough pancakes. Refrigerate leftovers up to 4 days, or freeze up to 2 months; reheat 1 minute from the fridge, 2 minutes from the freezer.","source":{"url":"https://www.jaroflemons.com/cottage-cheese-pancakes/","name":"Jar of Lemons"},"updatedAt":"2026-10-20T12:00:00Z"}', '2026-10-20T12:00:00Z');
INSERT OR REPLACE INTO recipes (slug, json, updated_at) VALUES ('creamy-lentil-stuffed-butternut-squash', '{"slug":"creamy-lentil-stuffed-butternut-squash","title":"Creamy Lentil Stuffed Butternut Squash","description":"","tags":["Vegetarian"],"servings":"4","prepTime":"20 min","cookTime":"1 hr 15 min","image":"","ingredients":["2 medium butternut squashes","Olive or avocado oil, for roasting","Kosher salt and freshly cracked black pepper","2/3 tbsp olive oil (more if not using nonstick)","1⅓ large yellow onions, diced","4 cloves garlic, minced","2/3 tbsp chopped fresh sage","1⅓ tsp chopped fresh rosemary","1⅓ tbsp tomato paste","3.6 tbsp (53⅓ ml) dry red wine (pinot noir, shiraz/syrah, or malbec)","2/3 cup (126⅔ g) green or brown lentils","1.8 cups (426⅔ ml) vegetable broth","2/3 bay leaf","2/3 tsp sweet or hot paprika","1⅔ tbsp tahini","1⅓ tsp white miso paste","1⅓ to 2 tsp good-quality balsamic vinegar","2/3 cup roasted butternut squash (from the scooped-out halves)","1⅓ tbsp tahini (for sauce)","2/3 tbsp extra virgin olive oil","2 to 4 tbsp water or vegetable broth, to thin sauce","Salt and pepper to taste","Chopped Italian flat-leaf parsley, for garnish"],"steps":["Preheat oven to 425°F. Halve squashes and scoop out seeds. Place cut side up on a baking sheet, rub with oil, and season with salt and pepper. Roast 45 to 50 minutes until fork tender and lightly browned.","Heat olive oil in a large pan over medium-high heat. Sauté onions with a pinch of salt for 8 to 9 minutes until mostly browned. Add garlic, sage, and rosemary; cook 2 minutes. Add tomato paste; cook 2 to 3 minutes.","Reduce heat to medium, add red wine, deglaze, and cook until the liquid evaporates and the alcohol smell dissipates, 2 to 3 minutes.","Add vegetable broth, lentils, bay leaf, and paprika. Bring to a boil, then reduce to a rapid simmer until the lentils are tender and most liquid is absorbed, about 30 minutes.","Reduce heat to low; stir in tahini, miso, and balsamic vinegar. Season with salt and pepper to taste.","When the squash is cool enough to handle, scoop out the flesh, leaving a ½ to ¾ inch border.","Transfer 1 cup squash flesh to a food processor (reserve the rest for another use).","Reduce oven to 350°F.","Stuff lentil filling into the squash cavities; bake 15 minutes until warmed through.","Make the sauce: blend the 1 cup squash flesh with tahini, olive oil, salt, and pepper. Stream in water or broth until pourable but thick.","Serve stuffed squash drizzled with tahini sauce, garnished with parsley."],"notes":"","source":{"url":"","name":"rainbowplantlife.com"},"updatedAt":"2026-10-20T12:00:00Z"}', '2026-10-20T12:00:00Z');
INSERT OR REPLACE INTO recipes (slug, json, updated_at) VALUES ('fresh-green-salad', '{"slug":"fresh-green-salad","title":"Fresh Green Salad","description":"Fresh, healthy, and delicious. Leftovers are even better the next day.","tags":["Salads"],"servings":"Not specified","prepTime":"Not specified","cookTime":"None (no cooking required)","image":"","ingredients":["½ green cabbage, shredded","1 fennel bulb, sliced thin","4 celery ribs, chopped (leaves included if available)","3 green onions, chopped","1 green apple, thinly sliced into strips","2 Serrano chilies with seeds (optional, for a kick)","½ bunch fresh mint, chopped","½ bunch fresh cilantro, chopped","Olive oil","Fresh lemon juice","1 tbsp salt"],"steps":["Chop, slice, toss, and enjoy."],"notes":"","source":{"url":"","name":"sivanskitchen"},"updatedAt":"2026-10-20T12:00:00Z"}', '2026-10-20T12:00:00Z');
INSERT OR REPLACE INTO recipes (slug, json, updated_at) VALUES ('greek-lemon-chicken', '{"slug":"greek-lemon-chicken","title":"Greek Lemon Chicken","description":"Juicy, tender, and crisp chicken thighs baked coated in a delicious lemon-herb marinade.","tags":["Other"],"servings":"8 pieces","prepTime":"15 min","cookTime":"40 min","image":"","ingredients":["8 bone-in, skin-on chicken thighs","1/3 cup extra-virgin olive oil","1/4 cup fresh lemon juice","4 garlic cloves, minced","1 tbsp dried oregano","2 tsp dried thyme","2 tsp Dijon mustard","2 tsp kosher salt","1 tsp freshly ground black pepper"],"steps":["Prepare marinade: Mix oil, lemon juice, garlic, oregano, thyme, mustard, salt, and pepper in a bowl.","Marinate: Place chicken in a large bowl, add marinade, toss, and refrigerate 1 to 2 hours (up to 8 hours).","Transfer: Preheat oven to 350°F (180°C). Arrange chicken skin-side up in a baking dish, pour remaining marinade over top.","Bake: Cook 40 to 45 minutes until internal temperature reaches 165°F. Broil 2 to 3 minutes for extra crispy skin if desired."],"notes":"Do not marinate longer than 3 hours with acidic marinades; texture becomes mushy. Boneless thighs cook faster; check at 30 to 35 minutes. Freezes well up to 3 months; reheat gently with added moisture.","source":{"url":"https://downshiftology.com/recipes/greek-lemon-chicken/","name":"Downshiftology"},"updatedAt":"2026-10-20T12:00:00Z"}', '2026-10-20T12:00:00Z');
INSERT OR REPLACE INTO recipes (slug, json, updated_at) VALUES ('healthy-honey-garlic-slow-cooker-chicken', '{"slug":"healthy-honey-garlic-slow-cooker-chicken","title":"Healthy Honey Garlic Slow Cooker Chicken","description":"This healthy honey garlic chicken recipe takes no time to throw together using your crock-pot or slow cooker. Just five ingredients and kid-friendly!","tags":["Other"],"servings":"Not specified","prepTime":"Not specified","cookTime":"4 hours on high","image":"","ingredients":["4 chicken breasts","1/2 cup honey","1/2 cup soy sauce","1/4 cup water","2 tbsp balsamic vinegar","1 tbsp minced garlic"],"steps":["Spray crock-pot with non-stick spray.","Mix honey, soy sauce, water, vinegar, and garlic in a bowl.","Place chicken breasts in crock-pot.","Pour the sauce over chicken.","Cook on high for 4 hours."],"notes":"Serve over rice with roasted vegetables. Leftover chicken works well on salads, sandwiches, and soups. One commenter recommended adding chicken thighs to prevent dryness.","source":{"url":"https://www.hellospoonful.com/healthy-honey-garlic-chicken-slow-cooker-recipe/","name":"Hello Spoonful"},"updatedAt":"2026-10-20T12:00:00Z"}', '2026-10-20T12:00:00Z');
INSERT OR REPLACE INTO recipes (slug, json, updated_at) VALUES ('honey-roasted-zaatar-chicken-with-dried-fruit', '{"slug":"honey-roasted-zaatar-chicken-with-dried-fruit","title":"Honey Roasted Za''atar Chicken with Dried Fruit","description":"Za''atar and olive oil create a fragrant paste that infuses the chicken as it braises over sweet dried apricots and prunes. A final drizzle of honey and a hot oven finish it off with a glaze.","tags":["Other"],"servings":"4 to 6","prepTime":"Not specified","cookTime":"1 hr 30 min to 1 hr 45 min","image":"","ingredients":["10 oz (scant 2 cups) dried apricots","10 oz (scant 2 cups) pitted dried prunes","3 tbsp za''atar","2 tbsp olive oil","4 chicken legs, skin-on","½ cup dry red wine","Kosher salt, to taste","½ cup honey"],"steps":["Preheat oven to 350°F. Spread apricots and prunes into a 9x13-inch pan.","Combine za''atar and olive oil into a paste; rub over the chicken. Place chicken on top of the dried fruit. Pour wine around the chicken and sprinkle with salt.","Cover tightly with foil; bake 1 hour.","Uncover, drizzle with honey. Bake uncovered an additional 30 to 45 minutes, basting every 10 minutes with pan juices."],"notes":"Meat dish; freezer friendly.","source":{"url":"","name":""},"updatedAt":"2026-10-20T12:00:00Z"}', '2026-10-20T12:00:00Z');
INSERT OR REPLACE INTO recipes (slug, json, updated_at) VALUES ('lemon-garlic-chicken-pitas-with-feta-tzatziki-and-roasted-bell-peppers', '{"slug":"lemon-garlic-chicken-pitas-with-feta-tzatziki-and-roasted-bell-peppers","title":"Lemon-Garlic Chicken Pitas with Feta Tzatziki & Roasted Bell Peppers","description":"A bright and flavorful meal featuring lemon-garlic chicken, charred roasted peppers, and creamy feta tzatziki, all stuffed in warm pitas.","tags":["Other"],"servings":"4 (1 pita per person)","prepTime":"15 min active, plus 30 min marinating","cookTime":"15 to 20 min","image":"","ingredients":["2 chicken breasts","Juice of 2 lemons","3 cloves garlic, minced","4 pita breads","1 cup feta cheese, crumbled","1 cup Greek yogurt","1 cucumber, grated","2 roasted red bell peppers","2 tbsp olive oil","Salt, to taste","Pepper, to taste","Fresh dill or parsley, chopped"],"steps":["Marinate chicken in lemon juice, garlic, olive oil, salt, and pepper for a minimum of 30 minutes.","Cook chicken by grilling (6 to 8 minutes per side) or baking at 425°F for 18 to 22 minutes until internal temperature reaches 165°F.","Prepare tzatziki by combining Greek yogurt, crumbled feta, grated cucumber (excess moisture squeezed out), garlic, and herbs. Season to taste.","Toast pita in a skillet for 30 to 60 seconds per side.","Assemble pitas with sliced chicken, roasted peppers, and tzatziki. Serve immediately."],"notes":"Marinate longer for deeper flavor. Use low-sodium options to reduce overall sodium content. Keep components separate if storing, to prevent sogginess.","source":{"url":"https://www.simplyrecip.com/lemon-garlic-chicken-pitas-feta-tzatziki-roasted-peppers/","name":"Simply Recip"},"updatedAt":"2026-10-20T12:00:00Z"}', '2026-10-20T12:00:00Z');
INSERT OR REPLACE INTO recipes (slug, json, updated_at) VALUES ('meat-pillows', '{"slug":"meat-pillows","title":"Meat Pillows","description":"Meatballs made with the gnocchi method, simmered in a balsamic marinara sauce.","tags":["Other"],"servings":"6","prepTime":"15 min","cookTime":"50 min","image":"","ingredients":["2 tbsp light olive oil","1 medium onion, finely diced","2 (26-ounce) jars marinara sauce","1/4 cup balsamic vinegar","1/3 cup low-sodium soy sauce","1 large egg","2 tbsp almond milk or soy milk","1 slice sandwich bread, crumbled","2 lb ground beef","1/2 tsp kosher salt","1/2 tsp garlic powder","1/2 tsp onion powder","1/2 tsp dried oregano","1/4 tsp pepper"],"steps":["Make the sauce (5 min): In a large stockpot, heat the olive oil over medium-high heat. Add the onion and sauté until softened, 4 to 5 minutes. Add the marinara sauce, balsamic vinegar, and soy sauce and bring to a simmer.","Make the meat mixture: In a large bowl, whisk together the egg and milk. Sprinkle in the bread and mash until fully broken up. Add the ground beef, salt, garlic powder, onion powder, oregano, and pepper. Mix until just incorporated.","Shape the pillows: Place two long sheets of plastic wrap on the counter. Divide the meat mixture in half and place each half in a log in the center of a sheet. Fold both sides of the plastic around the meat to form a long log, like sushi, then twist the ends like a salami. Squeeze to press the mixture together. Open the plastic and slice each log into roughly 15 pillows, about 30 total.","Simmer (45 min): Gently lower the pillows into the sauce and stir very gently to submerge them without breaking them. Shake the pot carefully every 5 to 10 minutes until everything is submerged. Cover and simmer over medium-low heat for 40 to 50 minutes. Let cool completely, then store covered in the fridge."],"notes":"Chop the onions for the meat pillows all at once to save a step later. For standard meatballs instead, roll the mixture into about 30 balls rather than using the gnocchi method.","source":{"url":"","name":"Nostalgic Magic, p. 157"},"updatedAt":"2026-10-20T12:00:00Z"}', '2026-10-20T12:00:00Z');
INSERT OR REPLACE INTO recipes (slug, json, updated_at) VALUES ('peach-cobbler', '{"slug":"peach-cobbler","title":"Peach Cobbler","description":"","tags":["Baking"],"servings":"8","prepTime":"15 min","cookTime":"45 min","image":"","ingredients":["7 tbsp unsalted butter (100 g)","6 large ripe yellow peaches (about 900 g)","¼ cup packed light brown sugar (55 g)","¼ cup granulated sugar (50 g)","1 cup all-purpose flour (120 g)","¾ cup granulated sugar (150 g)","2 tsp baking powder","½ tsp cinnamon","¼ tsp salt","¾ cup whole milk (180 ml)"],"steps":["Preheat oven to 375°F. Cut butter into pats, place in a 9x13 baking dish, and warm in the oven until melted, about 5 minutes. Set aside.","Peel, halve, pit, and slice peaches into ¼-inch pieces; transfer to a large skillet.","Sprinkle with brown and granulated sugar, mix, and cook over medium heat a few minutes until the sugars dissolve. Remove from heat.","Mix flour, baking powder, salt, sugar, and cinnamon; stir in milk until just combined.","Pour batter into the baking dish, spreading to the edges (do not mix with the butter).","Spread peaches with any liquid evenly over the batter, leaving gaps for the topping to rise through.","Bake 40 to 45 minutes, until golden brown and springs back when pressed."],"notes":"","source":{"url":"","name":"preppykitchen.com"},"updatedAt":"2026-10-20T12:00:00Z"}', '2026-10-20T12:00:00Z');
INSERT OR REPLACE INTO recipes (slug, json, updated_at) VALUES ('pickled-red-onions', '{"slug":"pickled-red-onions","title":"Pickled Red Onions","description":"A sweet and tangy pop of flavor for salads, sandwiches, and burgers.","tags":["Other"],"servings":"12","prepTime":"5 min","cookTime":"5 min","image":"","ingredients":["2 small red onions","2 cups white vinegar","2 cups water","½ cup cane sugar","2 tbsp sea salt","Optional: 2 garlic cloves, 1 tsp mixed peppercorns"],"steps":["Thinly slice onions; divide between 2 (16-oz) jars or 3 (10-oz) jars. Add garlic and peppercorns if using.","Heat vinegar, water, sugar, and salt in a medium saucepan over medium heat, stirring until dissolved, about 1 minute. Cool slightly, pour over the onions, cool to room temperature, then refrigerate.","Ready once bright pink and tender: about 1 hour for thin slices, overnight for thicker slices. Keeps in the fridge up to 2 weeks."],"notes":"Equipment: 10-oz Mason jars (or 16-oz jars), a mandoline, and a medium pot.","source":{"url":"","name":""},"updatedAt":"2026-10-20T12:00:00Z"}', '2026-10-20T12:00:00Z');
INSERT OR REPLACE INTO recipes (slug, json, updated_at) VALUES ('potato-kugel', '{"slug":"potato-kugel","title":"Potato Kugel","description":"","tags":["Vegetarian"],"servings":"About 2 pans","prepTime":"Not specified","cookTime":"2 hours, or longer if needed","image":"","ingredients":["9 variety-size gold potatoes","4 eggs","¾ cup olive oil or regular oil","1 onion","About 1 tbsp salt"],"steps":["Grate potatoes and onion (do not strain the liquid; it all goes in).","Mix grated potatoes and onion with eggs, oil, and salt.","Spray two pans well; divide the mixture between them, keeping it fairly shallow for even baking.","Bake at 350°F for 2 hours, or longer if needed."],"notes":"","source":{"url":"","name":""},"updatedAt":"2026-10-20T12:00:00Z"}', '2026-10-20T12:00:00Z');
INSERT OR REPLACE INTO recipes (slug, json, updated_at) VALUES ('sheet-pan-chicken-and-potatoes-with-honey-garlic-butter-sauce', '{"slug":"sheet-pan-chicken-and-potatoes-with-honey-garlic-butter-sauce","title":"Sheet Pan Chicken and Potatoes with Honey-Garlic Butter Sauce","description":"A one-pan dinner featuring crispy potatoes and juicy chicken coated in a glossy honey-garlic butter sauce. Comes together quickly with minimal effort.","tags":["Other"],"servings":"4","prepTime":"10 min","cookTime":"30 min","image":"","ingredients":["2 boneless, skinless chicken breasts (1.5 lb)","1 lb baby Yukon gold potatoes, halved","2 tbsp oil (olive or avocado)","1 tsp garlic powder","1 tsp black pepper","1 tsp paprika","2 tsp Kinder''s Buttery Steakhouse seasoning","3 tbsp unsalted butter","½ cup honey","2 cloves garlic, minced","½ tsp black pepper","¼ tsp salt"],"steps":["Preheat oven to 400°F. Toss potatoes and chicken with oil and dry spices on a sheet pan in a single layer.","Bake 25 to 30 minutes, flipping the potatoes at the 15-minute mark, until crispy.","While baking, melt butter in a small saucepan. Add garlic, sizzle 30 seconds, then stir in honey, salt, and pepper. Simmer 2 to 3 minutes.","Drizzle sauce over finished chicken and potatoes. Rest 5 minutes before serving."],"notes":"Per serving: about 460 calories, 30 g protein, 36 g carbs, 22 g fat, 3 g fiber.","source":{"url":"https://flavorscroll.com/sheet-pan-chicken-and-potatoes-with-honey-garlic-butter-sauce/","name":"Flavorscroll"},"updatedAt":"2026-10-20T12:00:00Z"}', '2026-10-20T12:00:00Z');
INSERT OR REPLACE INTO recipes (slug, json, updated_at) VALUES ('sourdough-bread', '{"slug":"sourdough-bread","title":"Sourdough Bread","description":"","tags":["Baking"],"servings":"1 loaf","prepTime":"1 hr 15 min active, plus ~12 hr bulk ferment and 10–36 hr cold proof","cookTime":"35 min","image":"","ingredients":["Room temperature water: 325 g","Salt: 10 g","Sourdough starter: 20 to 30 g (more if the house is colder or you have less time)","Bread flour or flour blend: 450 g","Flour scald: 35 g flour mixed with 70 g water (a different flour like khorasan, rye, spelt, or whole wheat adds flavor)"],"steps":["Prepare the scald: combine flour and boiling water, mixing thoroughly with no dry spots.","Add water, salt, and starter to the bowl; mix to break up the scald and starter and dissolve the salt.","Add the flour and mix very well for a few minutes.","Autolyse: rest at room temperature for at least 15 minutes.","Bulk fermentation with 4 sets of stretch and folds (about 45 min): stretch dough upward without tearing, fold over itself, rotate the container 90 degrees, and repeat until the dough stops stretching. Wait at least 15 minutes (up to 30 is better) between sets, for a total of 4 sets.","After all folds, cover and let ferment at room temperature overnight or all day (about 12 hours from first mix, depending on starter amount and temperature). Warmer water, more starter, or a warmer spot speeds this up.","Shape as preferred.","Refrigerate 10 to 36 hours (or bake right away in a pinch).","Bake: preheat fully to 480°F. Bake 20 min covered with ice, then uncovered until dark, about 15 more minutes."],"notes":"Straight-from-the-fridge starter works well if fed within the past week. After 2 weeks it rises slower (still OK) — feed it a day or few days ahead if it''s been that long. The flour blend is bread flour, whole milled sifted flour, extra fine semolina, and a small amount of rye; any flour works, but the water amount may need adjusting.","source":{"url":"","name":"Nissen"},"updatedAt":"2026-10-20T12:00:00Z"}', '2026-10-20T12:00:00Z');
INSERT OR REPLACE INTO recipes (slug, json, updated_at) VALUES ('tabbouleh', '{"slug":"tabbouleh","title":"Tabbouleh","description":"Middle Eastern herb and bulgur salad — zingy, fragrant, and so refreshing. Perfect for a mezze platter or picnic!","tags":["Salads"],"servings":"6","prepTime":"20 min","cookTime":"20 min","image":"","ingredients":["⅓ cup extra-virgin olive oil","3 tbsp fresh lemon juice","1 garlic clove, grated","½ tsp sea salt","¼ tsp ground coriander","Pinch cinnamon","3 cups finely chopped curly parsley (about 2 bunches)","1 cup diced English cucumber","1 cup cored and diced tomato","⅔ cup cooked bulgur wheat","⅓ cup finely chopped fresh mint","2 scallions, chopped"],"steps":["Whisk together olive oil, lemon juice, garlic, salt, coriander, and cinnamon in a large bowl.","Add parsley, cucumber, tomato, bulgur, mint, and scallions; toss to combine.","Season to taste and chill until serving."],"notes":"Coarse bulgur: boil 2 cups water, add 1 cup dry bulgur, cover, and remove from heat. Let sit 20 to 30 minutes until tender, then drain excess water and fluff with a fork; use ⅔ cup cooked bulgur, cooled before adding. Fine bulgur: place in a bowl, cover with ½ inch water, and soak 20 minutes until tender, then drain.","source":{"url":"https://www.loveandlemons.com/tabbouleh/","name":"Love and Lemons"},"updatedAt":"2026-10-20T12:00:00Z"}', '2026-10-20T12:00:00Z');
